'use client';

import { useSearchParams, useRouter } from 'next/navigation';
import { useForm, FormProvider } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { bookingSchema, BookingFormData } from './schema';
import StepServices from './StepServices';
import StepStaff from './StepStaff';
import StepTimeSlot from './StepTimeSlot';
import StepSummary from './StepSummary';

const STEPS = ['services', 'staff', 'slot', 'summary'] as const;
type Step = typeof STEPS[number];

export default function BookingFlow() {
  const searchParams = useSearchParams();
  const router = useRouter();
  const currentStep = (searchParams.get('step') as Step) || 'services';

  const methods = useForm<BookingFormData>({
    resolver: zodResolver(bookingSchema),
    mode: 'onTouched',
    defaultValues: {
      serviceId: '',
      staffId: '',
      date: '',
      timeSlot: '',
      customerName: '',
      phone: '',
    },
  });

  const goToStep = (nextStep: Step) => {
    const params = new URLSearchParams(searchParams.toString());
    params.set('step', nextStep);
    router.push(`?${params.toString()}`);
  };

  return (
    <FormProvider {...methods}>
      <div className="max-w-2xl mx-auto p-6 bg-white rounded-xl shadow-sm border border-slate-200">
        {/* Progress Bar */}
        <nav aria-label="Booking Progress" className="flex items-center justify-between mb-8">
          {STEPS.map((step, idx) => (
            <div key={step} className="flex items-center gap-2">
              <span className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-semibold ${
                currentStep === step ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-600'
              }`}>
                {idx + 1}
              </span>
              <span className="capitalize text-xs font-medium text-slate-700 hidden sm:inline">
                {step}
              </span>
            </div>
          ))}
        </nav>

        {/* Step Views */}
        {currentStep === 'services' && <StepServices onNext={() => goToStep('staff')} />}
        {currentStep === 'staff' && <StepStaff onNext={() => goToStep('slot')} onBack={() => goToStep('services')} />}
        {currentStep === 'slot' && <StepTimeSlot onNext={() => goToStep('summary')} onBack={() => goToStep('staff')} />}
        {currentStep === 'summary' && <StepSummary onBack={() => goToStep('slot')} />}
      </div>
    </FormProvider>
  );
}

import { useFormContext } from 'react-hook-form';
import { BookingFormData } from './schema';

interface StepProps {
  onNext: () => void;
  onBack?: () => void;
}

export default function StepServices({ onNext }: StepProps) {
  const { register, trigger, formState: { errors } } = useFormContext<BookingFormData>();

  const handleContinue = async () => {
    // Validate only the serviceId field before moving forward
    const isValid = await trigger('serviceId');
    if (isValid) {
      onNext();
    }
  };

  return (
    <div className="space-y-6">
      <h3 className="text-xl font-bold text-slate-900">Select a Service</h3>
      {/* Service list component selection */}
      <input type="hidden" {...register('serviceId')} />

      {errors.serviceId && (
        <p className="text-sm text-red-600">{errors.serviceId.message}</p>
      )}

      <button
        type="button"
        onClick={handleContinue}
        className="w-full py-3 px-4 bg-indigo-600 hover:bg-indigo-700 text-white font-medium rounded-lg transition-colors"
      >
        Continue to Staff Selection
      </button>
    </div>
  );
}

import { motion, AnimatePresence } from 'framer-motion';

const variants = {
  enter: (direction: number) => ({
    x: direction > 0 ? 50 : -50,
    opacity: 0,
  }),
  center: {
    x: 0,
    opacity: 1,
  },
  exit: (direction: number) => ({
    x: direction < 0 ? 50 : -50,
    opacity: 0,
  }),
};

export function StepContainer({ children, direction }: { children: React.ReactNode; direction: number }) {
  return (
    <AnimatePresence mode="wait" custom={direction}>
      <motion.div
        custom={direction}
        variants={variants}
        initial="enter"
        animate="center"
        exit="exit"
        transition={{ duration: 0.25, ease: 'easeOut' }}
      >
        {children}
      </motion.div>
    </AnimatePresence>
  );
}
